+      // Only place regular regions with live data or pinned regions into the candidate set.
@@ -437,2 +437,1 @@
-      if (!region->has_live()) {
-        assert(!region->is_pinned(), "Pinned region should have live (pinned) objects.");
+      if (!region->has_live() && !region->is_pinned()) {
@@ -448,5 +447,3 @@
-      // This will handle humongous start regions whether they are also pinned, or not.
-      // If they are pinned, we expect them to hold live data, so they will not be
-      // turned into immediate garbage.
-      if (!region->has_live()) {
-        assert(!region->is_pinned(), "Pinned region should have live (pinned) objects.");
+      // This will handle humongous start regions. If the region is pinned and dead, we cannot
+      // reclaim it, so skip it.
+      if (!region->has_live() && !region->is_pinned()) {

@@ -570,1 +570,3 @@
-        _heap->trash_humongous_region_at(r);
+        if (!r->is_pinned()) {
+          _heap->trash_humongous_region_at(r);
+        }
@@ -576,1 +578,4 @@
-      assert(r->humongous_start_region()->has_live(), "Region %zu should have live", r->index());
+      // unless it's pinned. Pinned regions cannot be reclaimed even when dead.
+      DEBUG_ONLY(ShenandoahHeapRegion* start = r->humongous_start_region();)
+      assert(start->has_live() || start->is_pinned(),
+             "Humongous start %zu of continuation %zu should have live or be pinned", start->index(), r->index());
